(() => {
  'use strict';
  const KEY='little-spark.v1';
  const $=(s,r=document)=>r.querySelector(s);
  const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid=()=>globalThis.crypto?.randomUUID?.()||`spark-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const now=()=>new Date().toISOString();
  const dateText=(v)=>{if(!v)return '';const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?v+'T12:00:00+08:00':v);return Number.isNaN(+d)?'':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric'}).format(d)};
  const minutes=v=>{if(!/^\d{2}:\d{2}$/.test(v||''))return NaN;const [h,m]=v.split(':').map(Number);return h<24&&m<60?h*60+m:NaN};
  const timeText=m=>`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
  const validDate=v=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return false;const d=new Date(v+'T12:00:00+08:00');return !Number.isNaN(+d)&&new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)===v;};
  const clockMinutes=()=>{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()).split(':').map(Number);return parts[0]*60+parts[1];};
  const suggestedSlot=()=>{const start=Math.ceil((clockMinutes()+5)/15)*15;if(start+30<1440)return {date:today(),start:timeText(start),end:timeText(start+30)};const d=new Date(today()+'T12:00:00+08:00');d.setTime(d.getTime()+86400000);return {date:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d),start:'18:30',end:'19:00'};};
  const typeName=t=>({skill:'学一点技能',creative:'试一个创意',park:'先放进口袋'}[t]||'一个小想法');
  const statusName=s=>({accepted:'等你试一试',done:'完成啦',partial:'尝试了一点',skipped:'这次先暂停',proposed:'等你确认'}[s]||'等你试一试');
  const paths={home:'M3 10l7-6 7 6M5 9v9h10V9M8 18v-6h4v6',ideas:'M5 8h10l2 9H3l2-9zm2 0V6a3 3 0 016 0v2m-5 4h4',plan:'M4 4h12v13H4V4zm3-2v4m6-4v4M4 8h12m-9 4h2m2 0h2m-6 3h2',lab:'M7 3h6M8 3v6l-5 7a1 1 0 001 2h12a1 1 0 001-2l-5-7V3M6 13h8',feedback:'M4 3h12v12H9l-5 3V3zm3 5h6m-6 3h4',spark:'M10 2l2.5 5.5L18 10l-5.5 2.5L10 18l-2.5-5.5L2 10l5.5-2.5L10 2z',arrow:'M4 10h12m-5-5l5 5-5 5',clock:'M10 18a8 8 0 100-16 8 8 0 000 16zm0-12v5l3 2',heart:'M10 17S2 12 2 7a4 4 0 018-1 4 4 0 018 1c0 5-8 10-8 10z',check:'M4 10l4 4 8-8',link:'M8 3h9v9m0-9L7 13M3 6v11h11v-4',plus:'M10 4v12M4 10h12',mic:'M10 13a3 3 0 003-3V5a3 3 0 00-6 0v5a3 3 0 003 3zm-6-3a6 6 0 0012 0m-6 6v3m-3 0h6',trace:'M5 3v14m0-10h8m-8 6h8M3 3h4m-4 14h4m6-10h3m-3 6h3'};
  const icon=name=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
  const resources=links=>`<div class="resource-links">${(links||[]).filter(x=>/^https:\/\//.test(x.url||'')).map(x=>`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.label)}${icon('link')}</a>`).join('')}</div>`;
  const defaultState=()=>({version:1,ideas:[],tasks:[],feedback:[],availability:{},notes:[],chatContext:{},createdAt:now()});
  let state=defaultState(),storageOK=true;
  try {const data=JSON.parse(localStorage.getItem(KEY));if(data&&validImport(data))state=data;}catch{storageOK=false;}
  PocketFlow.normalize(state);
  let view='home',filter='all',selectedIdea=null,selectedTask=null,planResult=null,labResult=null,reflection=null;
  let energy='medium',level='beginner',completion='done',feeling='right',bots=[],miniBot,expressionBot,lastTrace=[],pendingIdea=null,pendingMedia=null,previewURL=null,mediaDB=null,recognizer=null;
  const main=$('#main'),dialog=$('#dialog');
  function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toasts').append(node);setTimeout(()=>node.remove(),4500);}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true;}catch{storageOK=false;toast('浏览器没有保存成功。请先导出记录，避免刷新后丢失。',true);return false;}}
  function activeIdeas(type){return state.ideas.filter(i=>!i.archived&&(!type||i.type===type));}
  function ideaById(id){return state.ideas.find(i=>i.id===id);}
  function taskById(id){return state.tasks.find(t=>t.id===id);}
  function latestFeedback(ideaId){return [...state.feedback].reverse().find(f=>f.ideaId===ideaId);}
  function initBot(container,emotion='happy',size='hero'){if(!container||!window.RobotCompanion)return null;const bot=RobotCompanion.mount(container,{size});bot.setEmotion(emotion);bots.push(bot);return bot;}
  function mood(emotion,line){bots.forEach(b=>b.setEmotion(emotion));miniBot?.setEmotion(emotion);if(line&&$('#robot-speech'))$('#robot-speech').textContent=line;}
  function temporaryMood(emotion,line){mood(emotion,line);const route=view;setTimeout(()=>{if(view===route)mood('happy','每个小想法，我都有认真听见。');},3500);}
  function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();}
  function closeDialog(){dialog.close();expressionBot?.destroy();expressionBot=null;}
  function traceLink(trace){lastTrace=trace||[];return `<button class="trace-button" data-action="trace">${icon('trace')}看看这一步如何完成</button>`;}
  function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
  function go(route,ideaId,taskId){selectedIdea=ideaId||selectedIdea;selectedTask=taskId||selectedTask;planResult=null;labResult=null;reflection=null;if(location.hash!=='#'+route)history.pushState(null,'','#'+route);view=route;render();window.scrollTo({top:0,behavior:'instant'});}
  function renderNav(){const routes=[['home','我的小窝'],['ideas','灵感口袋'],['plan','学习小步'],['lab','创意实验室'],['feedback','成长回声']];$('#nav').innerHTML=routes.map(([key,label])=>`<a class="nav-item ${view===key?'active':''}" href="#${key}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='ideas'?`<span class="nav-badge">${activeIdeas().length}</span>`:''}</a>`).join('');}
  function render(){bots.forEach(b=>b.destroy());bots=[];if(recognizer){recognizer.stop();recognizer=null;}renderNav();({home:renderHome,ideas:renderIdeas,plan:renderPlan,lab:renderLab,feedback:renderFeedback}[view]||renderHome)();if(!storageOK)toast('这个浏览器暂时不能保存记录，你仍可体验并导出文字记录。',true);}
  function overdue(t){return t.status==='accepted'&&Date.now()>+new Date(`${t.date}T${t.end}:00+08:00`);}
  function homeTask(t){return `<div class="home-task"><div class="home-task-top"><strong>${e(t.title)}</strong><span class="time-pill ${overdue(t)?'overdue':''}">${overdue(t)?'听听你的进展':e(t.start+'–'+t.end)}</span></div><p>${dateText(t.date)} · ${e(t.duration)} 分钟 · ${e(ideaById(t.ideaId)?.title||'一个小尝试')}</p><div class="home-task-actions"><button class="btn small secondary" data-action="task-detail" data-id="${e(t.id)}">查看小步骤</button><button class="btn small secondary" data-action="feedback-task" data-id="${e(t.id)}">${icon('feedback')}说说进展</button>${overdue(t)?`<button class="text-button" data-action="missed" data-id="${e(t.id)}">这次没做</button>`:''}</div></div>`;}
  function renderHome(){const pending=state.tasks.filter(t=>t.status==='accepted').sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));const done=state.tasks.filter(t=>t.status==='done').length;const total=state.feedback.reduce((s,f)=>s+(Number(f.minutes)||0),0);
    main.innerHTML=heading('欢迎回到你的灵感小窝','这里收藏好奇，也容纳偶尔的三分钟热度。','<span class="pill-label">✦ 慢慢来也很好</span>')+`
      <section class="hero" aria-label="皮皮的欢迎"><div class="hero-copy"><div class="eyebrow"><i>✦</i>A LITTLE SPARK, A LITTLE STEP</div><h2>三分钟的热情，<br><em>也能亮很久。</em></h2><p>学一点、试一下、慢慢来。<br>让皮皮替你记住，突如其来的喜欢。</p><div class="button-row"><button class="btn primary" data-action="new-idea">${icon('plus')}和皮皮聊聊</button><a class="btn ghost" href="#plan">看看今天的小步${icon('arrow')}</a></div></div><div class="hero-stage"><div class="speech-bubble" id="robot-speech">每个小想法，我都有认真听见。</div><i class="stage-spark one">✦</i><i class="stage-spark two">✧</i><i class="stage-spark three">✦</i><i class="floating-heart">♡</i><div class="hero-robot-button" data-action="pet-robot"><div id="hero-robot"></div></div><div class="robot-play-controls"><span>拖动皮皮转一转 · 点一下摸摸它</span><button data-action="spin-robot" aria-label="让皮皮旋转一圈">↻ 转一圈</button><button data-action="reset-robot" aria-label="让皮皮转回正面">回正面</button></div></div></section>
      <div class="stats-row"><div class="stat"><div class="stat-icon">${icon('ideas')}</div><div><strong>${activeIdeas().length}<small>个</small></strong><p>好好收着的灵感</p></div></div><div class="stat"><div class="stat-icon">${icon('check')}</div><div><strong>${done}<small>次</small></strong><p>完成了一小步</p></div></div><div class="stat"><div class="stat-icon">${icon('clock')}</div><div><strong>${total}<small>分钟</small></strong><p>留给喜欢的时间</p></div></div></div>
      <div class="home-grid"><section class="panel capture-panel"><div class="panel-header"><h2>${icon('spark')}想说什么，都放进来</h2><span>灵感记录员 · 01</span></div><p>不用选 Agent，也不用填一堆表。说想法，说时间，皮皮来接力。</p><form id="quick-idea-form"><label class="sr-only" for="quick-idea">你的新想法</label><textarea id="quick-idea" name="idea" maxlength="1500" required placeholder="比如：我想学跳舞，明天十二点试十分钟，我是小白……"></textarea><div class="inspiration-chips"><button type="button" data-action="suggest" data-text="我想学一小段街舞，完全零基础">♫ 学一小段舞</button><button type="button" data-action="suggest" data-text="我想练唱歌，能开心唱完一首就好">♪ 练练唱歌</button><button type="button" data-action="suggest" data-text="我想组织一次校园音乐分享会">✦ 一个天马行空的点子</button></div><div class="capture-footer"><span>Enter 发送 · Shift + Enter 换行</span><button class="btn" type="submit">告诉皮皮${icon('arrow')}</button></div></form></section>
      <section class="panel"><div class="panel-header"><h2>${icon('plan')}今天，走一小步</h2><a class="text-button" href="#plan">全部计划 ${icon('arrow')}</a></div>${pending.length?pending.slice(0,2).map(homeTask).join(''):`<div class="empty-mini"><div class="empty-icon">☁</div><div><strong>今天的小格子，还空着</strong><p>有时间就试一试，没时间也没关系。</p><a class="text-button" href="#plan">安排一个轻轻的小行动 ${icon('arrow')}</a></div></div>`}<p class="small-note">${icon('heart')}计划是给生活留一点喜欢，记得也给自己留一点休息。</p></section></div>
      <div class="section-title"><h2>四个小帮手，把灵感接力下去</h2><span>从一个念头，到一点点收获</span></div><div class="agents-row"><button class="agent-card" data-action="new-idea"><span class="agent-number">AGENT 01</span><div class="agent-glyph">✦</div><strong>灵感记录员</strong><p>接住你突然的喜欢<br>好想法，都先收好</p></button><a class="agent-card" href="#plan"><span class="agent-number">AGENT 02</span><div class="agent-glyph">◷</div><strong>学习安排员</strong><p>找到有空的小格子<br>量力而行，慢慢来</p></a><a class="agent-card" href="#lab"><span class="agent-number">AGENT 03</span><div class="agent-glyph">⚗</div><strong>创意探索员</strong><p>为天马行空的点子<br>找到一次小小的尝试</p></a><a class="agent-card" href="#feedback"><span class="agent-number">AGENT 04</span><div class="agent-glyph">♡</div><strong>行动反馈员</strong><p>听听你真实的感受<br>再一起调整下一步</p></a></div>
      <div class="onboarding-card">${icon('spark')}<div><strong>第一次来？和皮皮试一段小故事。</strong><p>加入明确标注的示例，体验「想学跳舞 → 小计划 → 反馈调整」。</p></div><button class="btn small secondary" data-action="demo-story">体验一下 ${icon('arrow')}</button></div>`;
    initBot($('#hero-robot'));}
  function rambleComposer(){return '<form id="ramble-form" class="ramble-composer"><label for="ramble-text">随便和皮皮说</label><textarea id="ramble-text" name="ramble" maxlength="1500" rows="3" required placeholder="我想学跳舞……那就明天十二点学吧。今天有点累，先试五分钟。"></textarea><div class="ramble-send"><span>一句或一段都可以 · Enter 发送</span><button class="btn primary" type="submit">告诉皮皮 '+icon('arrow')+'</button></div></form>';}
  function renderIdeas(){
    const labels={1:'灵感记录员',2:'学习安排员',3:'创意探索员',4:'行动反馈员'},last=state.notes.at(-1),current=ideaById(state.chatContext.lastIdeaId),list=activeIdeas();
    const messages=state.notes.length?state.notes.map(n=>'<article class="ramble-turn" data-note-id="'+e(n.id)+'"><div class="ramble-user"><span>我的碎碎念 · '+e(dateText(n.createdAt))+'</span><p>'+e(n.text)+'</p></div><div class="ramble-pipi"><div class="reply-heading"><span class="pipi-avatar">✦</span><strong>皮皮</strong><div class="agent-receipts">'+(n.agents||[1]).map(a=>'<span class="receipt a'+a+'">'+e(labels[a]||'灵感记录员')+'</span>').join('')+'</div></div><p>'+e(n.reply)+'</p>'+(n.links||[]).map(link=>'<button class="ramble-result-link" data-action="note-link" data-value="'+e(link.view)+'" data-id="'+e(link.ideaId||'')+'" data-task-id="'+e(link.taskId||'')+'">✓ '+e(link.label)+' '+icon('arrow')+'</button>').join('')+(PocketFlow.canUndo(n.id,state)&&n.changed&&!n.undone?'<button class="undo-note" data-action="undo-note" data-id="'+e(n.id)+'">撤销刚才的自动改动</button>':'')+'</div></article>').join(''):'<div class="ramble-welcome"><span class="welcome-glyph">✦</span><h2>想法可以碎碎的，我会帮你接起来。</h2><p>“我想学跳舞。”<br>“那要不十二点学吧。”<br>“今天只练了五分钟，有点难。”</p><small>灵感、时间、反馈会自动交给对应的小帮手。没听清时，我只问你一句。</small></div>';
    main.innerHTML=heading('灵感口袋','碎碎念尽管说，接下来的事让皮皮串起来。','<span class="pill-label">✦ 一个入口，四个小帮手</span>')+'<div class="ramble-layout"><section class="panel ramble-panel"><div class="ramble-status"><i class="online-dot"></i><strong>皮皮在听</strong><span>'+(current?'接着聊：'+e(current.title):'每句原话都会好好留下')+'</span></div><div id="ramble-history" class="ramble-history" aria-live="polite">'+messages+'</div>'+rambleComposer()+'</section><aside class="pocket-sidebar"><section class="panel pocket-handoffs"><span class="eyebrow">PIPI CONNECTS THE DOTS</span><h2>小帮手，收到啦</h2>'+[[1,'ideas',state.notes.length+' 句碎碎念','先收好每句原话'],[2,'plan',state.tasks.filter(t=>t.kind==='learning').length+' 个学习小步','想学什么，什么时候有空'],[3,'lab',list.filter(i=>i.type==='creative').length+' 个创意','先找到可以试的一步'],[4,'feedback',state.feedback.length+' 次反馈','从真实的感受调整下一步']].map(([a,route,count,line])=>'<a class="handoff-row a'+a+'" href="#'+route+'"><span class="handoff-number">0'+a+'</span><div><strong>'+labels[a]+'</strong><small>'+line+'</small></div><em>'+count+'</em></a>').join('')+'<p class="pocket-hint">这些是自动归属的结果，继续在口袋说就好。</p></section><details class="panel pocket-topics"><summary>收好的喜欢 · '+list.length+'</summary>'+(list.length?list.map(i=>'<div class="pocket-topic"><span class="idea-type">'+typeName(i.type)+'</span><strong>'+e(i.title)+'</strong><p>'+e(i.text)+'</p><button class="text-button" data-action="continue-topic" data-id="'+e(i.id)+'">接着聊这个喜欢</button></div>').join(''):'<p>从一个“我想……”开始就好。</p>')+'</details><div class="pocket-tiny-note">记录保存在当前浏览器。演示版能识别常见表达，还未连接真实大模型。</div></aside></div>';
    const history=$('#ramble-history');if(history)history.scrollTop=history.scrollHeight;
  }
  
  function ideaOptions(type){const list=activeIdeas(type);return list.map(i=>`<option value="${e(i.id)}" ${selectedIdea===i.id?'selected':''}>${i.sample?'示例 · ':''}${e(i.title)}</option>`).join('');}
  function ensureIdea(type){if(!activeIdeas(type).some(i=>i.id===selectedIdea))selectedIdea=activeIdeas(type)[0]?.id||null;}
  function renderManualPlan(){ensureIdea('skill');const prior=latestFeedback(selectedIdea);const slot=suggestedSlot();main.innerHTML=heading('把喜欢，放进有空的一小格','基础、时间和精力都算数。安排好之后，由你决定留不留下。','<span class="pill-label">学习安排员 · 02</span>')+`<div class="two-column"><section class="panel"><h2 class="form-title">今天想学一点什么？</h2><p class="form-intro">先告诉皮皮，你今天能给自己留多少空间。</p>${activeIdeas('skill').length?`<form id="plan-form"><div class="form-grid"><div class="field full"><label for="plan-idea">挑一个口袋里的喜欢</label><select id="plan-idea" name="ideaId">${ideaOptions('skill')}</select></div><div class="field"><label for="plan-date">哪一天有空？</label><input id="plan-date" type="date" name="date" value="${slot.date}" min="${today()}" required></div><div class="field"><label for="plan-duration">想试多久？</label><select id="plan-duration" name="duration"><option value="5">5 分钟 · 轻轻碰一下</option><option value="10" selected>10 分钟 · 走一小步</option><option value="20">20 分钟 · 认真试试</option><option value="30">30 分钟 · 多学一点</option><option value="45">45 分钟 · 深入探索</option></select></div><div class="field"><label for="plan-start">可用时间 · 从</label><input id="plan-start" name="availableStart" type="time" value="${slot.start}" required></div><div class="field"><label for="plan-end">可用时间 · 到</label><input id="plan-end" name="availableEnd" type="time" value="${slot.end}" required></div><div class="field full"><span class="label">现在的精力怎么样？</span><div class="segmented" role="group" aria-label="选择精力">${[['low','☁ 有点累'],['medium','☺ 还不错'],['high','✦ 电量满满']].map(([v,l])=>`<button type="button" class="${energy===v?'selected':''}" data-action="energy" data-value="${v}" aria-pressed="${energy===v}">${l}</button>`).join('')}</div></div><div class="field full"><span class="label">你之前有基础吗？</span><div class="segmented" role="group" aria-label="选择基础">${[['beginner','完全小白'],['some','会一点点'],['advanced','想继续深入']].map(([v,l])=>`<button type="button" class="${level===v?'selected':''}" data-action="level" data-value="${v}" aria-pressed="${level===v}">${l}</button>`).join('')}</div></div><div class="field full"><label for="plan-goal">想学到什么程度？<small>（可以先不确定）</small></label><input id="plan-goal" name="goal" maxlength="200" placeholder="比如：能开心跳完一小段就好"></div></div><div class="form-separator"></div><div class="field full"><span class="label">这段时间里，还有哪些安排？</span><small>把没空的时段加进来，皮皮会绕开它们。</small><div id="busy-slots"></div><button class="text-button" type="button" data-action="add-busy">${icon('plus')}添加没空的时段</button></div>${prior?`<div class="helper-note" id="prior-note">♡ 记得你上次的感受：${e(prior.nextAdjustment?.advice||prior.summary)}。这次会一起考虑。</div>`:''}<div class="form-actions"><button class="btn primary" type="submit">${icon('spark')}帮我安排一小步</button><span>生成后再确认，想改就改。</span></div></form>`:`<div class="empty-mini"><div class="empty-icon">✦</div><div><strong>先放一个想学的技能进口袋</strong><p>皮皮会替你记住，再一起安排。</p><button class="text-button" data-action="new-idea" data-type="skill">记录我想学的 ${icon('arrow')}</button></div></div>`}</section><section id="plan-result" class="panel result-panel placeholder"><div class="placeholder-symbol">◷</div><h2>给好奇心，留一小格时间</h2><p>有空的时候学一点。<br>有点累，就把行动缩小一点。<br>你确认之前，计划都只是一份建议。</p></section></div><section class="task-section"><div class="section-title"><h2>已经约好的小行动</h2><span>不同的喜欢，进度都会留下</span></div>${renderTaskList()}</section>`;if(planResult)showPlanResult();}
  function renderPlan(){
    ensureIdea('skill');const savedPreferences=ideaById(selectedIdea)?.preferences||{};energy=savedPreferences.energy||energy;level=savedPreferences.level||level;
    renderManualPlan();const columns=$('.two-column',main),tasks=$('.task-section',main);
    if(columns){const detail=document.createElement('details');detail.className='manual-settings';detail.open=!!planResult;detail.innerHTML='<summary>想手动微调时，再展开这些设置</summary>';columns.replaceWith(detail);detail.append(columns);if(tasks)detail.before(tasks);}
    const description=$('.page-heading p',main);if(description)description.textContent='在灵感口袋说一句时间，皮皮会直接安排到这里。';
    const info=document.createElement('div');info.className='auto-plan-note';info.innerHTML='✦ 不用先填表，直接说“明天十二点学跳舞，试十分钟”就好。<a href="#ideas">去和皮皮聊聊 '+icon('arrow')+'</a>';$('.page-heading',main)?.after(info);
    const current=ideaById(selectedIdea),pref=current?.preferences||{},task=state.tasks.find(t=>t.id===state.chatContext.lastTaskId&&t.ideaId===selectedIdea&&t.status==='accepted');
    if(task&&$('#plan-date')){$('#plan-date').value=task.date;$('#plan-start').value=task.start;$('#plan-end').value=task.end;}
    const duration=task?.duration||pref.duration,selector=$('#plan-duration');if(duration&&selector){if(![...selector.options].some(o=>Number(o.value)===Number(duration))){const option=document.createElement('option');option.value=String(duration);option.textContent=duration+' 分钟';selector.append(option);}selector.value=String(duration);}
    if(pref.goal&&$('#plan-goal'))$('#plan-goal').value=pref.goal;
  }
  function renderTaskList(){const list=[...state.tasks].sort((a,b)=>(b.date+b.start).localeCompare(a.date+a.start));return list.length?`<div class="task-list">${list.map(t=>`<article class="task-card ${e(t.status)}"><div class="task-status-icon">${{done:'✓',partial:'♡',skipped:'☁',accepted:'◷'}[t.status]||'◷'}</div><div class="task-info"><h3>${e(t.title)}</h3><p>${dateText(t.date)} ${e(t.start)}–${e(t.end)} · ${e(t.duration)} 分钟 · ${e(ideaById(t.ideaId)?.title||'一个小尝试')}</p></div><span class="task-status">${statusName(t.status)}</span><button class="text-button" data-action="task-detail" data-id="${e(t.id)}">查看步骤</button>${t.status==='accepted'?`<button class="btn small secondary" data-action="feedback-task" data-id="${e(t.id)}">反馈一下</button>`:`<button class="text-button" data-action="next-step" data-id="${e(t.id)}">下一小步 ${icon('arrow')}</button>`}</article>`).join('')}</div>`:`<div class="empty-mini"><div class="empty-icon">☁</div><div><strong>还没有约定，也不用着急</strong><p>你接受的小计划会出现在这里。</p></div></div>`;}
  function showPlanResult(){const box=$('#plan-result');if(!box)return;box.classList.remove('placeholder');const r=planResult;const tasks=r.tasks||[];box.innerHTML=`<span class="pill-label">◷ 量力而行的小安排</span><h2 class="result-heading" style="margin-top:15px">${tasks.length?dateText(r.date)+'，只做这一小步':'先给自己留一点空间'}</h2>${r.error?`<div class="notice">${e(r.error)}</div>`:''}<p class="result-rationale">${e(r.rationale||'这段时间不够完成一个小行动，可以换个空闲时段。')}</p>${tasks.map(t=>`<div class="plan-step"><div class="step-meta"><span>${e(t.start)}–${e(t.end)}</span><span>${e(t.duration)} 分钟</span></div><h3>${e(t.title)}</h3><p>${e(t.description)}</p>${resources(t.resources)}</div>`).join('')}${tasks.length?`<div class="button-row"><button class="btn primary" data-action="accept-plan">${icon('check')}这个安排可以</button><button class="btn secondary" data-action="reject-plan">先放下，改一改</button></div>`:''}<p class="small-note">${e(r.nextAdvice||'教程按钮是搜索入口，你可以自己挑一位喜欢的老师。')}</p>${traceLink(r.trace)}`;}
  function renderLab(){ensureIdea('creative');if(!labResult&&ideaById(selectedIdea)?.exploration)labResult={...ideaById(selectedIdea).exploration,ideaId:selectedIdea,timeBudget:ideaById(selectedIdea).preferences?.duration||10};const prior=latestFeedback(selectedIdea);main.innerHTML=heading('天马行空，也可以先落地一点','不急着证明整个想法。先找一个小问题，试一次就知道更多。','<span class="pill-label">创意探索员 · 03</span>')+`<div class="two-column"><section class="panel"><h2 class="form-title">把点子放到小实验台</h2><p class="form-intro">我们一起找条件、找路径，也欢迎你反问和补充。</p>${activeIdeas('creative').length?`<form id="lab-form"><div class="form-grid"><div class="field full"><label for="lab-idea">今天探索哪个点子？</label><select id="lab-idea" name="ideaId">${ideaOptions('creative')}</select></div><div class="field full"><label for="lab-details">还有什么细节、疑问或另一条路径？</label><textarea id="lab-details" name="details" maxlength="1200" placeholder="比如：我想到另一种方法，先拉三个同学做一个小群，行不行？"></textarea></div><div class="field full"><label for="lab-resources">现在有什么条件？</label><input id="lab-resources" name="resources" maxlength="250" placeholder="比如：我和两个朋友、一个手机、暂时没有预算"></div><div class="field full"><label for="lab-budget">这一次愿意投入多久？</label><select id="lab-budget" name="timeBudget"><option value="10">10 分钟 · 摸摸可行性</option><option value="20" selected>20 分钟 · 做一次小验证</option><option value="30">30 分钟 · 动手试一下</option></select></div></div>${prior?`<div class="helper-note peach">上次留下的观察：${e(prior.reason||prior.summary)}。这一次，会沿着已有尝试继续。</div>`:''}<div class="form-actions"><button class="btn primary" type="submit">${icon('lab')}找一个可尝试的路径</button></div></form>`:`<div class="empty-mini"><div class="empty-icon">⚗</div><div><strong>你的点子，值得一个小实验</strong><p>先记录一个想做出来的东西或活动。</p><button class="text-button" data-action="new-idea" data-type="creative">记录一个创意 ${icon('arrow')}</button></div></div>`}</section><section id="lab-result" class="panel result-panel lab-result placeholder"><div class="placeholder-symbol">⚗</div><h2>先试一下，再知道一点</h2><p>一个能验证的小行动，<br>比一份遥远的大计划更容易开始。<br>皮皮会把“还不确定”也认真记下来。</p></section></div>`;if(labResult)showLabResult();}
  function showLabResult(){const box=$('#lab-result');if(!box)return;box.classList.remove('placeholder');const r=labResult;box.innerHTML=`<span class="pill-label">✦ 一次小小的可行性探索</span><h2 class="result-heading" style="margin-top:15px">${e(r.title||'先找到一个可试的方向')}</h2><h3 class="subheading">先确认这些小假设</h3><div class="number-list">${(r.assumptions||[]).map((s,i)=>`<div><span class="number">${i+1}</span><span>${e(typeof s==='string'?s:s.text||s.title)}</span></div>`).join('')}</div><h3 class="subheading">可以怎么走？</h3><div class="number-list">${(r.paths||[]).map((p,i)=>`<div><span class="number">${i+1}</span><span><strong>${e(p.title)}</strong><br>${e(p.description)}</span></div>`).join('')}</div><div class="plan-step"><div class="step-meta"><span>第一次小验证</span></div><h3>${e(typeof r.firstStep==='string'?r.firstStep:r.firstStep?.title||'做一次小尝试')}</h3>${typeof r.firstStep==='object'?`<p>${e(r.firstStep.description)}</p>`:''}<p>怎样算有收获：${e(r.successSignal)}</p></div><button class="btn primary" data-action="schedule-experiment">${icon('check')}给这一步留个时间</button><h3 class="subheading">还可以继续问自己</h3><p class="result-rationale">${(r.questions||[]).map(q=>e(q)).join('<br>')}</p>${resources(r.searchLinks)}<p class="small-note">这些是搜索入口和待验证的方向，尚未查证为真实可行的结论。</p>${traceLink(r.trace)}`;}
  function renderFeedback(){const pending=state.tasks.filter(t=>t.status==='accepted');if(!pending.some(t=>t.id===selectedTask))selectedTask=pending[0]?.id||null;main.innerHTML=heading('做了多少，都可以告诉我','完成、试了一点，或者今天没做。真实的感受，是下一步的起点。','<span class="pill-label">行动反馈员 · 04</span>')+`<div class="two-column"><section class="panel"><h2 class="form-title">今天的小行动，怎么样了？</h2><p class="form-intro">皮皮听你说，然后一起把下一次安排得更合适。</p>${pending.length?`<form id="feedback-form"><div class="form-grid"><div class="field full"><label for="feedback-task">想聊哪一个小行动？</label><select id="feedback-task" name="taskId">${pending.map(t=>`<option value="${e(t.id)}" ${t.id===selectedTask?'selected':''}>${e(t.title)} · ${dateText(t.date)}</option>`).join('')}</select></div><div class="field full"><span class="label">这一次做到哪里了？</span><div class="segmented" role="group" aria-label="完成情况">${[['done','✓ 完成啦'],['partial','♡ 做了一点'],['skipped','☁ 这次没做']].map(([v,l])=>`<button type="button" class="${completion===v?'selected':''}" data-action="completion" data-value="${v}" aria-pressed="${completion===v}">${l}</button>`).join('')}</div></div><div class="field"><label for="feedback-minutes">实际尝试了多久？</label><input id="feedback-minutes" name="minutes" type="number" min="0" max="480" value="${e(completion==='skipped'?0:taskById(selectedTask)?.duration||10)}" required></div><div class="field"><label for="feedback-next">下次可能有空的日期</label><input id="feedback-next" name="nextAvailable" type="date" min="${today()}" value=""></div><div class="field full"><span class="label">难度感觉怎么样？</span><div class="segmented" role="group" aria-label="练习难度">${[['easy','轻轻松松'],['right','刚刚好'],['hard','有点难']].map(([v,l])=>`<button type="button" class="${feeling===v?'selected':''}" data-action="feeling" data-value="${v}" aria-pressed="${feeling===v}">${l}</button>`).join('')}</div></div><div class="field full"><label for="feedback-reason">有什么想告诉皮皮的？</label><textarea id="feedback-reason" name="reason" maxlength="1500" placeholder="比如：今天临时加了课，回来太累了。或者：动作太难，只练了五分钟。" ${completion==='skipped'?'required':''}></textarea><button type="button" class="text-button" data-action="voice">${icon('mic')}用语音说一说</button><small>语音转文字需要浏览器支持；不支持时，也可以直接打字。</small></div><div class="field full"><label for="feedback-media">留一份成果 <small>（可选）</small></label><input id="feedback-media" type="file" accept="video/*,audio/*,image/*" capture="user"><small>视频、录音或照片，仅保存在此浏览器；最多 25 MB。用于记录成果，暂不评估动作或音准。</small><div id="upload-preview" class="upload-preview"></div></div></div><div class="form-actions"><button class="btn primary" type="submit">${icon('feedback')}告诉皮皮</button><span>你的反馈会改变下一次建议。</span></div></form>`:`<div class="empty-mini"><div class="empty-icon">♡</div><div><strong>先有一个小行动，再来聊聊感受</strong><p>学习或创意的小尝试，都可以反馈。</p><a class="text-button" href="#plan">安排一个小行动 ${icon('arrow')}</a></div></div>`}</section><section id="feedback-result" class="panel result-panel feedback-result placeholder"><div id="feedback-robot" class="feedback-robot"></div><h2>今天的你，也值得被理解</h2><p>没有完成，不代表没有认真。<br>告诉皮皮发生了什么，<br>下次我们把小步子调得更舒服。</p></section></div><section class="feedback-history"><div class="section-title"><h2>留下来的成长回声</h2><span>每一次尝试，都算数</span></div>${state.feedback.length?[...state.feedback].reverse().map(f=>`<article class="feedback-item"><span class="feedback-icon">${f.completion==='done'?'✓':f.completion==='partial'?'♡':'☁'}</span><div><h3>${e(f.taskTitle)} <small>· ${dateText(f.createdAt)} · ${e(f.minutes)} 分钟</small></h3><p>${e(f.reason||f.summary)}</p><div class="adjustment">下一次：${e(f.nextAdjustment?.advice||'根据这一次的感受，继续走一小步。')}</div>${f.attachment?`<button class="attachment-link" data-action="view-media" data-id="${e(f.id)}">查看成果 · ${e(f.attachment.name)}</button>`:''}</div></article>`).join(''):`<div class="empty-mini"><div class="empty-icon">♡</div><div><strong>这里会留下你的尝试与感受</strong><p>换了兴趣，之前的收获也还在。</p></div></div>`}</section>`;initBot($('#feedback-robot'),completion==='skipped'?'angry':'happy');if(reflection)showReflection();}
  function showReflection(){const box=$('#feedback-result');if(!box)return;box.classList.remove('placeholder');const r=reflection;box.innerHTML=`<div id="feedback-robot" class="feedback-robot"></div><h2 class="result-heading">${r.completion==='skipped'?'刚刚是皮皮着急了':'谢谢你，认真告诉我'}</h2><div class="feedback-response">${e(r.response)}</div><div class="helper-note purple">下一次的小调整：${e(r.nextAdjustment?.advice||r.summary)}</div><button class="btn secondary" data-action="next-step" data-id="${e(r.taskId||selectedTask)}">下次有空，再走一小步 ${icon('arrow')}</button>${traceLink(r.trace)}`;initBot($('#feedback-robot'),r.emotion||'sorry');}
  function newIdea(){closeDialog();go('ideas');$('#ramble-text')?.focus();}
  function captureIdea(text){
    const value=String(text||'').trim();if(!value)return;
    const note=PocketFlow.submit(value,state,{now:now(),today:today(),clockMinutes:clockMinutes()});
    if(!note)return;save();closeDialog();selectedIdea=state.chatContext.lastIdeaId;selectedTask=state.chatContext.lastTaskId;go('ideas',selectedIdea,selectedTask);mood(note.emotion||'happy');$('#ramble-text')?.focus();
  }
  
  function routeIdea(id){const i=ideaById(id);if(!i)return;closeDialog();if(i.archived){i.archived=false;save();}if(i.type==='park'){openDialog(`<h2>今天，想怎么拾起这个喜欢？</h2><p class="dialog-intro">${e(i.title)}</p><div class="question-options"><button data-action="activate-idea" data-id="${e(id)}" data-value="skill">把它当技能学<span>安排一点练习时间</span></button><button data-action="activate-idea" data-id="${e(id)}" data-value="creative">把它当创意试<span>做一次小实验</span></button></div><button class="text-button" data-action="close-dialog">继续好好收藏</button>`);return;}go(i.type==='skill'?'plan':'lab',id);}
  function validateSchedule(tasks,date){if(!validDate(date)||date<today())return '请选择今天或之后有空的日期。';for(const t of tasks){const s=minutes(t.start),en=minutes(t.end);if(date===today()&&s<clockMinutes())return '这个时间已经过去啦。换一个之后有空的小格子吧。';if(!Number.isFinite(s)||!Number.isFinite(en)||en<=s)return '这个时间段不完整，换一个时间再试试。';if((state.availability?.[date]||[]).some(slot=>s<minutes(slot.end)&&en>minutes(slot.start)))return '这段时间你之前说过没空。换一个空闲的小格子吧。';if(state.tasks.some(saved=>saved.date===date&&saved.status!=='skipped'&&s<minutes(saved.end)&&en>minutes(saved.start)))return '这段时间已经有一个小行动了。换个空闲时段，皮皮不让喜欢挤在一起。';}return null;}
  function submitPlan(form){const fd=new FormData(form),idea=ideaById(fd.get('ideaId'));if(!idea)return;const date=fd.get('date');if(!validDate(date)||date<today()){toast('请选择今天或之后的日期。',true);return;}const busySlots=[...$('#busy-slots').children].map(row=>({start:$('input:first-of-type',row).value,end:$('input:last-of-type',row).value}));if(busySlots.some(s=>!Number.isFinite(minutes(s.start))||!Number.isFinite(minutes(s.end))||minutes(s.end)<=minutes(s.start))){toast('没空的时段需要有完整的开始和结束时间，结束要晚于开始。',true);return;}const personalBusy=busySlots.map(slot=>({...slot}));busySlots.push(...(state.availability?.[date]||[]));if(date===today()&&clockMinutes()>0)busySlots.push({start:'00:00',end:timeText(clockMinutes())});busySlots.push(...state.tasks.filter(t=>t.date===date&&t.status!=='skipped').map(t=>({start:t.start,end:t.end})));selectedIdea=idea.id;mood('thinking');planResult=SparkEngine.planLearning({idea:idea.text,title:idea.title,date,availableStart:fd.get('availableStart'),availableEnd:fd.get('availableEnd'),busySlots,energy,level,goal:fd.get('goal'),duration:Number(fd.get('duration')),adjustment:latestFeedback(idea.id)?.nextAdjustment});planResult.date=date;planResult.ideaId=idea.id;planResult.personalBusy=personalBusy;showPlanResult();if(!(planResult.tasks||[]).length){mood('no');toast(planResult.error||'这段时间先留给休息吧，可以再换一个时间。');}else mood('happy');if(innerWidth<981)$('#plan-result').scrollIntoView({behavior:'smooth',block:'start'});}
  function acceptPlan(){if(!planResult?.tasks?.length)return;const error=validateSchedule(planResult.tasks,planResult.date);if(error){mood('no');toast(error,true);return;}state.availability=state.availability||{};state.availability[planResult.date]=[...(state.availability[planResult.date]||[]),...(planResult.personalBusy||[])];const steps=planResult.tasks;const allResources=steps.flatMap(t=>t.resources||[]);state.tasks.push({id:uid(),ideaId:planResult.ideaId,date:planResult.date,title:(ideaById(planResult.ideaId)?.title||'喜欢的技能')+' · 一次小练习',start:steps[0].start,end:steps[steps.length-1].end,duration:steps.reduce((sum,t)=>sum+t.duration,0),description:steps.map(t=>t.title+'：'+t.description).join('\n'),steps,resources:allResources.filter((r,i)=>allResources.findIndex(item=>item.url===r.url)===i),status:'accepted',createdAt:now(),kind:'learning'});save();planResult=null;render();mood('proud');toast('这个小约定收好啦。到时候试一点就好。');}
  function submitLab(form){const fd=new FormData(form),idea=ideaById(fd.get('ideaId'));if(!idea)return;selectedIdea=idea.id;labResult=SparkEngine.exploreIdea({idea:idea.text+(fd.get('details')?'。我的补充和追问：'+fd.get('details'):''),resources:fd.get('resources'),timeBudget:Number(fd.get('timeBudget')),feedback:latestFeedback(idea.id)});labResult.ideaId=idea.id;labResult.timeBudget=Number(fd.get('timeBudget'));showLabResult();mood('excited');if(innerWidth<981)$('#lab-result').scrollIntoView({behavior:'smooth',block:'start'});}
  function scheduleExperiment(){if(!labResult)return;openDialog(`<div class="dialog-eyebrow">给创意一次小尝试</div><h2>留一个可以动手的小格子</h2><p class="dialog-intro">${e(typeof labResult.firstStep==='string'?labResult.firstStep:labResult.firstStep?.title)}</p><form id="experiment-form"><div class="form-grid"><div class="field"><label for="experiment-date">哪一天？</label><input id="experiment-date" type="date" name="date" min="${today()}" value="${suggestedSlot().date}" required></div><div class="field"><label for="experiment-time">几点开始？</label><input id="experiment-time" type="time" name="start" value="${suggestedSlot().start}" required></div><div class="field full"><label for="experiment-duration">愿意试多久？</label><select id="experiment-duration" name="duration"><option value="5">5 分钟</option><option value="10" selected>10 分钟</option><option value="20">20 分钟</option><option value="30">30 分钟</option></select></div></div><div class="form-actions"><button class="btn primary" type="submit">${icon('check')}保留这一步</button><button class="btn secondary" type="button" data-action="close-dialog">先放下</button></div></form>`);$('#experiment-duration').value=String(labResult.timeBudget||10);}
  function submitExperiment(form){const fd=new FormData(form),start=fd.get('start'),duration=Number(fd.get('duration')),endMin=minutes(start)+duration;if(!labResult)return;if(!Number.isFinite(endMin)||endMin>=1440){toast('这个小行动跨过午夜了，换一个稍早的时间吧。',true);return;}const task={id:uid(),ideaId:labResult.ideaId,title:(typeof labResult.firstStep==='string'?labResult.firstStep:labResult.firstStep?.title||'一次创意小验证').replace(/\d+\s*分钟/g,duration+' 分钟'),description:typeof labResult.firstStep==='object'?labResult.firstStep.description:labResult.successSignal,date:fd.get('date'),start,end:timeText(endMin),duration,status:'accepted',createdAt:now(),kind:'experiment',resources:labResult.searchLinks||[]};const error=validateSchedule([task],task.date);if(error){mood('no');toast(error,true);return;}state.tasks.push(task);save();closeDialog();temporaryMood('proud');toast('小实验已约好，行动后记得说说你的发现。');go('plan');}
  async function openMediaDB(){if(mediaDB)return mediaDB;mediaDB=await new Promise((resolve,reject)=>{const req=indexedDB.open('little-spark-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return mediaDB;}
  async function putMedia(id,file){const db=await openMediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
  async function getMedia(id){const db=await openMediaDB();return new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  async function submitFeedback(form){const fd=new FormData(form),task=taskById(fd.get('taskId'));if(!task||task.status!=='accepted'){toast('这一步已有反馈啦，请选另一个小行动。',true);return;}const reason=String(fd.get('reason')||'').trim();if(completion==='skipped'&&!reason){toast('告诉皮皮发生了什么，让它好好听你说。',true);$('#feedback-reason').focus();return;}const spent=Number(fd.get('minutes'));if(!Number.isFinite(spent)||spent<0||spent>480){toast('尝试时间请填 0 到 480 分钟。',true);return;}const button=$('button[type=submit]',form);const submittedCompletion=completion,submittedFeeling=feeling,submittedMedia=pendingMedia;form.querySelectorAll('button,input,textarea,select').forEach(control=>control.disabled=true);selectedTask=task.id;const result=SparkEngine.reflect({task,reason,completion,minutes:completion==='skipped'?0:spent,feeling,nextAvailable:fd.get('nextAvailable')});const feedback={id:uid(),ideaId:task.ideaId,taskId:task.id,taskTitle:task.title,completion,minutes:completion==='skipped'?0:spent,feeling,reason,createdAt:now(),nextAvailable:fd.get('nextAvailable'),summary:result.summary,response:result.response,nextAdjustment:result.nextAdjustment};if(submittedMedia){try{await putMedia(feedback.id,submittedMedia);feedback.attachment={name:submittedMedia.name,type:submittedMedia.type,size:submittedMedia.size,local:true};}catch{toast('成果文件没能保存，文字反馈仍会留下。',true);}}if(pendingMedia===submittedMedia)pendingMedia=null;task.status=submittedCompletion;state.feedback.push(feedback);save();if(view==='feedback'&&$('#feedback-form')===form){completion=submittedCompletion;feeling=submittedFeeling;reflection={...result,taskId:task.id,completion:submittedCompletion};renderFeedback();mood(result.emotion||'sorry');if(innerWidth<981)$('#feedback-result').scrollIntoView({behavior:'smooth',block:'start'});}renderNav();toast('你的感受收好啦，下次会根据它来调整。');}
  function nextStep(taskId){const task=taskById(taskId),idea=ideaById(task?.ideaId);if(!idea)return;const feedback=latestFeedback(idea.id);if(idea.archived){idea.archived=false;save();toast('这个喜欢重新拾起来啦，接着上次的进度走。');}go(idea.type==='creative'?'lab':'plan',idea.id);if(view==='plan'&&$('#plan-duration')){const duration=Number(task.duration)||10;const select=$('#plan-duration');if(![...select.options].some(o=>Number(o.value)===duration)){const option=document.createElement('option');option.value=String(duration);option.textContent=duration+' 分钟 · 沿用上一次的小步';select.append(option);}select.value=String(duration);}if(view==='plan'&&$('#plan-date')&&feedback?.nextAvailable&&validDate(feedback.nextAvailable)&&feedback.nextAvailable>=today())$('#plan-date').value=feedback.nextAvailable;}
  function showExpressions(){openDialog(`<div class="dialog-eyebrow">PIPI'S LITTLE THEATRE</div><h2>皮皮的表情小剧场</h2><p class="dialog-intro">小机器人也有小情绪，但会认真听完你的解释。</p><div class="expression-stage"><div id="expression-robot"></div><p id="expression-line">今天也笑呵呵地陪着你。</p></div><div class="expression-buttons">${[['happy','☺ 笑呵呵'],['excited','✦ 好兴奋'],['thinking','◌ 想一想'],['proud','👍 点个赞'],['angry','哼，闹别扭'],['sorry','有点愧疚'],['no','双手比叉'],['sleepy','☁ 歇一下']].map(([v,l])=>`<button data-action="expression" data-value="${v}" class="${v==='happy'?'selected':''}">${l}</button>`).join('')}</div>`);expressionBot=RobotCompanion.mount($('#expression-robot'),{size:'hero'});}
  function showAbout(){openDialog(`<div class="dialog-eyebrow">关于这个温柔的小窝</div><h2>让每个小喜欢，都有一次尝试</h2><p class="dialog-intro">嗨皮瓜 · 三分钟热度。皮皮帮你记录、安排、探索和复盘。</p><div class="about-list"><div><strong>当前是可操作的演示版</strong>四个角色通过本地规则把碎碎念接到灵感、时间、创意和反馈里。可以连续接话，常见时间和精力表达会自动填入，暂未连接真实大模型。不会声称已经搜索网页或专业评估视频。</div><div><strong>你的记录，保存在这个浏览器</strong>文字保存在浏览器本地；成果文件保存在本地文件库。不同设备不会自动同步，清理浏览器数据会删除它们。可导出文字记录，成果文件请另行保留。</div><div><strong>你可以慢慢来，也可以换一个喜欢</strong>在口袋说清楚时间后，会自动保存小行动；可以撤销或改时间。手动生成的建议仍由你确认。暂停不等于失败，新兴趣也不会覆盖旧进度。日程仅作参考，精力由你自己告诉皮皮。</div></div><div class="form-actions"><button class="btn primary" data-action="close-dialog">知道啦，去和皮皮聊聊</button><button class="btn secondary" data-action="expressions">看看皮皮的表情</button></div>`);}
  function demoStory(){
    let idea=state.ideas.find(i=>i.sample&&i.type==='skill');
    if(!idea){const note=PocketFlow.submit('我想学一小段街舞，我是小白',state,{now:now(),today:today(),clockMinutes:clockMinutes()});idea=ideaById(note.ideaIds[0]);idea.sample=true;note.sample=true;note.reply='这是皮皮准备的示例，已经接给学习安排员啦。你可以接着说：“明天十二点试十分钟”。';}
    state.chatContext={lastIdeaId:idea.id,lastTaskId:null,pending:null};save();go('ideas',idea.id);$('#ramble-text')?.focus();toast('示例已标注。接着告诉皮皮什么时候有空就好。');
  }
  function exportData(){const data={...state,exportedAt:now(),note:'文字与成果文件信息；本地视频、录音和照片不包含在此文件中。'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`嗨皮瓜-灵感记录-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('文字记录已导出；视频、录音和照片请另行保留。');}
  function validImport(data){if(data?.notes){if(!Array.isArray(data.notes)||data.notes.length>2000||data.notes.some(n=>!n||typeof n.id!=='string'||n.id.length>100||typeof n.text!=='string'||n.text.length>1500||typeof n.reply!=='string'||n.reply.length>12000||typeof n.createdAt!=='string'||!Array.isArray(n.agents)||n.agents.some(a=>![1,2,3,4].includes(a))||n.links&&(!Array.isArray(n.links)||n.links.some(l=>!['ideas','plan','lab','feedback'].includes(l.view)))))return false;}if(!data||data.version!==1||!Array.isArray(data.ideas)||!Array.isArray(data.tasks)||!Array.isArray(data.feedback))return false;if(data.ideas.length>2000||data.tasks.length>5000||data.feedback.length>5000)return false;if(data.availability){if(typeof data.availability!=='object'||Array.isArray(data.availability))return false;for(const [date,slots] of Object.entries(data.availability)){if(!validDate(date)||!Array.isArray(slots)||slots.length>100||slots.some(slot=>!Number.isFinite(minutes(slot.start))||!Number.isFinite(minutes(slot.end))||minutes(slot.end)<=minutes(slot.start)))return false;}}const text=(v,max)=>typeof v==='string'&&v.length<=max;const ids=new Set();for(const i of data.ideas){if(!text(i.id,100)||ids.has(i.id)||!text(i.title,200)||!text(i.text,2000)||!['skill','creative','park'].includes(i.type))return false;ids.add(i.id);}const taskIds=new Set();for(const t of data.tasks){if(!text(t.id,100)||taskIds.has(t.id)||!ids.has(t.ideaId)||!text(t.title,1000)||!Number.isInteger(t.duration)||t.duration<1||t.duration>480||t.duration!==minutes(t.end)-minutes(t.start)||!validDate(t.date)||!Number.isFinite(minutes(t.start))||!Number.isFinite(minutes(t.end))||minutes(t.end)<=minutes(t.start)||!['accepted','done','partial','skipped'].includes(t.status))return false;taskIds.add(t.id);}for(const f of data.feedback){if(!text(f.id,100)||!ids.has(f.ideaId)||!taskIds.has(f.taskId)||!['done','partial','skipped'].includes(f.completion)||!Number.isFinite(Number(f.minutes))||Number(f.minutes)<0||Number(f.minutes)>480)return false;}return true;}
  document.addEventListener('click',ev=>{const button=ev.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,v=button.dataset.value,id=button.dataset.id;
    if(a==='new-idea')newIdea();
    else if(a==='spin-robot'){bots[0]?.spin?.();}
    else if(a==='reset-robot'){bots[0]?.resetRotation?.();}
    else if(a==='undo-note'){if(PocketFlow.undo(state,id)){save();renderIdeas();toast('自动改动已撤销，原话仍然留着。');}}
    else if(a==='note-link'){go(v,id,button.dataset.taskId);}
    else if(a==='continue-topic'){state.chatContext.lastIdeaId=id;state.chatContext.lastTaskId=state.tasks.filter(t=>t.ideaId===id&&t.status==='accepted').at(-1)?.id||null;state.chatContext.pending=null;save();renderIdeas();$('#ramble-text')?.focus();}
    else if(a==='close-dialog')closeDialog();
    else if(a==='about')showAbout();
    else if(a==='expressions')showExpressions();
    else if(a==='pet-robot')temporaryMood('excited','嘿嘿，被你摸摸，电量都变满啦！');
    else if(a==='suggest'){$('#quick-idea').value=button.dataset.text;$('#quick-idea').focus();temporaryMood('proud','这个小火花，听起来就很开心。');}
    else if(a==='filter'){filter=v;renderIdeas();}
    else if(a==='route-idea')routeIdea(id);
    else if(a==='archive'){const i=ideaById(id);if(i){i.archived=!i.archived;save();render();toast(i.archived?'先让这个喜欢休息一下，之前的进度还在。':'喜欢重新拾起来啦。');}}
    else if(a==='activate-idea'){const i=ideaById(id);if(i){i.type=v;save();routeIdea(id);}}
    else if(a==='classify-choice'&&pendingIdea){captureIdea(pendingIdea.text);pendingIdea=null;}
    else if(['energy','level','completion','feeling'].includes(a)){if(a==='energy')energy=v;if(a==='level')level=v;if(a==='feeling')feeling=v;if(a==='completion'){completion=v;$('#feedback-reason').required=v==='skipped';if(v==='skipped'){$('#feedback-minutes').value=0;mood('angry','哼，我先闹一点小别扭。发生什么啦？');}else{if(Number($('#feedback-minutes').value)===0)$('#feedback-minutes').value=taskById($('#feedback-task').value)?.duration||10;mood(v==='done'?'proud':'happy');}}button.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});}
    else if(a==='add-busy'){const row=document.createElement('div');row.className='busy-row';row.innerHTML='<input type="time" value="18:40" aria-label="没空的开始时间"><span>至</span><input type="time" value="18:50" aria-label="没空的结束时间"><button type="button" data-action="remove-busy" aria-label="移除这个没空的时段">×</button>';$('#busy-slots').append(row);}
    else if(a==='remove-busy')button.closest('.busy-row').remove();
    else if(a==='accept-plan')acceptPlan();
    else if(a==='reject-plan'){planResult=null;$('#plan-result').classList.add('placeholder');$('#plan-result').innerHTML='<div class="placeholder-symbol">☁</div><h2>先放下，也没关系</h2><p>刚才的建议没有保存。<br>改一下时间、精力或目标，再试一次。</p>';mood('happy');toast('建议已放下，你的计划里没有新增任务。');}
    else if(a==='schedule-experiment')scheduleExperiment();
    else if(a==='task-detail'){const task=taskById(id);if(task){openDialog(`<div class="dialog-eyebrow">${e(dateText(task.date))} · ${e(task.start)}–${e(task.end)} · ${e(task.duration)} 分钟</div><h2>${e(task.title)}</h2><p class="dialog-intro">${statusName(task.status)} · ${e(ideaById(task.ideaId)?.title||'一个小尝试')}</p>${task.steps?.length?task.steps.map(step=>`<div class="plan-step"><div class="step-meta"><span>${e(step.start)}–${e(step.end)}</span></div><h3>${e(step.title)}</h3><p>${e(step.description)}</p></div>`).join(''):`<div class="plan-step"><p>${e(task.description||'尝试一下，再告诉皮皮你的感受。')}</p></div>`}${resources(task.resources)}${task.status==='accepted'?`<div class="form-actions"><button class="btn primary" data-action="feedback-task" data-id="${e(task.id)}">说说进展</button></div>`:''}`);}}
    else if(a==='feedback-task'){closeDialog();completion='done';feeling='right';pendingMedia=null;go('feedback',null,id);}
    else if(a==='missed'){completion='skipped';feeling='right';pendingMedia=null;go('feedback',null,id);mood('angry');}
    else if(a==='next-step')nextStep(id);
    else if(a==='trace'){openDialog(`<div class="dialog-eyebrow">四个小帮手的接力过程</div><h2>这一小步，是怎么完成的？</h2><p class="dialog-intro">本地演示流程：读取你的输入、执行规则、保存结果并交接下一步。暂未调用真实大模型。</p><div class="trace-list">${lastTrace.map(t=>`<div class="trace-item"><span class="trace-icon">${{'Agent 1':'✦','Agent 2':'◷','Agent 3':'⚗','Agent 4':'♡'}[t.agent]||'✦'}</span><div><strong>${e(t.agent)} · ${e(t.action)}</strong><p>${e(t.detail)}</p></div></div>`).join('')}</div>`);}
    else if(a==='expression'){expressionBot?.setEmotion(v);const lines={happy:'今天也笑呵呵地陪着你。',excited:'有新灵感啦！天线都开心得晃起来。',thinking:'等一下，让我认真想想这个小安排。',proud:'双手点赞！每一次小尝试都很棒。',angry:'哼，约好的小任务呢？我先闹一下小别扭。',sorry:'听完你的解释，是我刚刚太着急了。',no:'No no no，别把所有空闲都塞满啦。',sleepy:'今天有点累，那就一起休息一下。'};$('#expression-line').textContent=lines[v];button.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===button));}
    else if(a==='demo-story')demoStory();
    else if(a==='export')exportData();
    else if(a==='import')$('#import-file').click();
    else if(a==='confirm-import'){const data=window.__sparkImport;if(data){const knownIdeas=new Set(state.ideas.map(i=>i.id)),knownTasks=new Set(state.tasks.map(t=>t.id)),knownFeedback=new Set(state.feedback.map(f=>f.id));state.ideas.push(...data.ideas.filter(i=>!knownIdeas.has(i.id)));state.tasks.push(...data.tasks.filter(t=>!knownTasks.has(t.id)));state.feedback.push(...data.feedback.filter(f=>!knownFeedback.has(f.id)).map(f=>({...f,attachment:f.attachment?{...f.attachment,local:false}:undefined})));state.availability={...(data.availability||{}),...(state.availability||{})};const knownNotes=new Set(state.notes.map(n=>n.id));state.notes.push(...(data.notes||[]).filter(n=>!knownNotes.has(n.id)));state.notes.sort((a,b)=>a.createdAt.localeCompare(b.createdAt));PocketFlow.normalize(state);save();window.__sparkImport=null;closeDialog();render();toast('文字记录合并完成，原来的记录也保留着。');}}
    else if(a==='voice'){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('这个浏览器暂不支持语音转文字。可以打字，或上传录音作为成果。');return;}if(recognizer){recognizer.stop();recognizer=null;return;}recognizer=new Speech();recognizer.lang='zh-CN';recognizer.interimResults=false;recognizer.onresult=event=>{const text=[...event.results].map(r=>r[0].transcript).join('');if($('#feedback-reason'))$('#feedback-reason').value+=text;};recognizer.onerror=()=>toast('没有听清，或麦克风未获授权。可以再试一次或直接打字。',true);recognizer.onend=()=>{recognizer=null;button.classList.remove('recording');button.innerHTML=icon('mic')+'用语音说一说';};button.classList.add('recording');button.textContent='正在听你说…点这里结束';try{recognizer.start();}catch{recognizer=null;toast('语音暂时没有启动，请直接打字。',true);}}
    else if(a==='view-media'){const feedback=state.feedback.find(f=>f.id===id);if(!feedback?.attachment)return;if(feedback.attachment.local===false){toast('导入文件只有成果信息，原始视频或录音仍在原来的浏览器。');return;}getMedia(id).then(file=>{if(!file){toast('成果文件不在这个浏览器中，请保留原始文件。',true);return;}if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(file);const tag=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'img';openDialog(`<div class="media-dialog"><h2>${e(feedback.attachment.name)}</h2><p class="dialog-intro">这是你留下的成果记录，不包含专业技能评估。</p><${tag} src="${previewURL}" ${tag!=='img'?'controls':''} ${tag==='img'?'style="max-width:100%"':''}></${tag}></div>`);}).catch(()=>toast('浏览器文件库暂时不可用。',true));}
  });
  document.addEventListener('submit',ev=>{const form=ev.target;if(!['quick-idea-form','new-idea-form','ramble-form','plan-form','lab-form','feedback-form','experiment-form'].includes(form.id))return;ev.preventDefault();if(!form.reportValidity())return;if(form.id==='ramble-form')captureIdea(new FormData(form).get('ramble'));if(form.id==='quick-idea-form')captureIdea(new FormData(form).get('idea'));if(form.id==='new-idea-form'){const fd=new FormData(form);captureIdea(fd.get('idea'),fd.get('type'));}if(form.id==='plan-form')submitPlan(form);if(form.id==='lab-form')submitLab(form);if(form.id==='feedback-form')submitFeedback(form).catch(()=>{toast('反馈没有完成保存，请再试一次。',true);form.querySelectorAll('button,input,textarea,select').forEach(control=>control.disabled=false);});if(form.id==='experiment-form')submitExperiment(form);});
  document.addEventListener('change',ev=>{const target=ev.target;if(target.id==='plan-idea'||target.id==='lab-idea'){selectedIdea=target.value;planResult=null;labResult=null;if(target.id==='plan-idea')renderPlan();else renderLab();}if(target.id==='feedback-task'){selectedTask=target.value;reflection=null;$('#feedback-minutes').value=completion==='skipped'?0:taskById(selectedTask)?.duration||10;}
    if(target.id==='feedback-media'){const file=target.files[0];pendingMedia=null;if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}$('#upload-preview').innerHTML='';if(!file)return;if(file.size>25*1024*1024){target.value='';toast('成果文件有点大，先选一个 25 MB 以内的片段吧。',true);return;}if(!/^(video|audio|image)\//.test(file.type)){target.value='';toast('请选择视频、录音或照片。',true);return;}pendingMedia=file;previewURL=URL.createObjectURL(file);const tag=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'img';$('#upload-preview').innerHTML=`<${tag} src="${previewURL}" ${tag!=='img'?'controls':''} ${tag==='img'?'style="max-width:100%;max-height:200px;border-radius:12px"':''}></${tag}><p>${e(file.name)} · ${(file.size/1024/1024).toFixed(1)} MB · 提交反馈后保存在本地</p>`;}
    if(target.id==='import-file'){const file=target.files[0];target.value='';if(!file)return;if(file.size>5*1024*1024){toast('记录文件过大，请选择本网站导出的文字记录。',true);return;}file.text().then(text=>{let data;try{data=JSON.parse(text);}catch{throw Error('invalid');}if(!validImport(data))throw Error('invalid');window.__sparkImport=data;openDialog(`<h2>把之前的小收获带回来</h2><p class="dialog-intro">找到 ${data.ideas.length} 条灵感、${data.tasks.length} 个小行动和 ${data.feedback.length} 次反馈。会合并到当前记录，不覆盖已有记录。</p><div class="helper-note">成果文件仅有名称等信息，视频与录音需在原来的浏览器或设备查看。</div><div class="button-row"><button class="btn primary" data-action="confirm-import">确认合并</button><button class="btn secondary" data-action="close-dialog">先不导入</button></div>`);}).catch(()=>toast('这不是有效的嗨皮瓜记录文件，当前记录没有改变。',true));}
  });
  document.addEventListener('keydown',event=>{if(['ramble-text','quick-idea'].includes(event.target.id)&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();event.target.form.requestSubmit();}});
  dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
  dialog.addEventListener('close',()=>{expressionBot?.destroy();expressionBot=null;});
  window.addEventListener('popstate',()=>{view=['home','ideas','plan','lab','feedback'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();});
  window.addEventListener('hashchange',()=>{view=['home','ideas','plan','lab','feedback'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();});
  $('#today-label').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'short'}).format(new Date());
  if(window.RobotCompanion)miniBot=RobotCompanion.mount($('#mini-robot'),{size:'small'});
  view=['home','ideas','plan','lab','feedback'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();
})();
